mapper.select:
SELECT A.PRJ_NO AS A_PRJ_NO, A.USER_ID AS A_USER_ID, A.AUTHORITY_CODE, A.DELETE_DATE AS A_DELETE_DATE,
B.PRJ_NO AS B_PRJ_NO, B.USER_ID AS B_USER_ID, B.PROJECT_BOARD_NO, B.PROJECT_NAME, B.PROJECT_CONTENTS, B.PROJECT_STATUS, B.CREATE_DATE, B.FINISH_DATE, B.DELETE_DATE AS B_DELETE_DATE
FROM PRJ_MEM A LEFT OUTER JOIN PROJECT B ON A.PRJ_NO = B.PRJ_NO WHERE A.USER_ID = #{userID}

mapper.insert:

    SELECT
        'PRJT'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(PRJ_NO), LENGTH('PRJT' ) + 1)), 0) + 1, 6, '0')
    FROM PROJECT

INSERT INTO PROJECT (
	PRJ_NO
	, USER_ID
	, PROJECT_BOARD_NO
	, PROJECT_NAME
	, PROJECT_CONTENTS
	, PROJECT_STATUS
	, CREATE_DATE
) VALUES (
	#{prjNo}
	, #{userId}
	, #{projectBoardNo}
	, #{projectName}
	, #{projectContents}
	, #{projectStatus}
	, SYSDATE
)

mapper.update:
UPDATE PROJECT
SET 
	PROJECT_NAME = #{projectName}
	, PROJECT_CONTENTS = #{projectContents}
	, PROJECT_STATUS = #{projectStatus}
WHERE PRJ_NO = #{prjNo}
